#' Advanced Reliability (SEM)
#'
#' 
#' @param data .
#' @param secondOrder .
#' @param factors .
#' @param showPlots .
#' @param plotStyle .
#' @param reportLang .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$fitTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$fitNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelComparisonTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modelComparisonNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plotFitComparison} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotFitComparisonNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reliabilityTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$reliabilityNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plotComparison} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotComparisonNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plotLoadings} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotLoadingsNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$htmtTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$htmtNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$omegaHNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modificationIndicesTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modificationIndicesNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$fitTable$asDF}
#'
#' \code{as.data.frame(results$fitTable)}
#'
#' @export
advancedReliability <- function(
    data,
    secondOrder = FALSE,
    factors = list(
                list(label="Factor 1", vars=list())),
    showPlots = TRUE,
    plotStyle = "gray",
    reportLang = "en") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("advancedReliability requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- advancedReliabilityOptions$new(
        secondOrder = secondOrder,
        factors = factors,
        showPlots = showPlots,
        plotStyle = plotStyle,
        reportLang = reportLang)

    analysis <- advancedReliabilityClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

